-- Single private workspace. Creator attribution is separated from member-readable content.
create extension if not exists pgcrypto;
create schema if not exists private;
revoke all on schema private from public, anon, authenticated;
create table public.profiles (id uuid primary key references auth.users(id), username text unique not null check(username ~ '^[a-z0-9_]{3,24}$'), role text not null default 'member' check(role in ('member','admin')), disabled boolean not null default false, created_at timestamptz not null default now());
create table public.ideas (id uuid primary key, data jsonb not null, accent text unique not null, version integer not null default 1, deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table private.attribution (idea_id uuid primary key references public.ideas(id), creator_id uuid not null references public.profiles(id));
create table private.revisions (id uuid primary key default gen_random_uuid(), idea_id uuid not null references public.ideas(id), actor uuid not null references public.profiles(id), data jsonb not null, created_at timestamptz not null default now());
create table private.invitations (token_hash text primary key, created_by uuid references public.profiles(id), expires_at timestamptz not null default now()+interval '7 days', consumed_at timestamptz);
create table private.audit (id uuid primary key default gen_random_uuid(), actor uuid not null references public.profiles(id), action text not null, target uuid, created_at timestamptz not null default now());
create table private.limits (key text primary key, hits integer not null, window_start timestamptz not null);
alter table public.profiles enable row level security;
alter table public.ideas enable row level security;
revoke all on public.profiles,public.ideas from anon,authenticated;
grant select on public.profiles,public.ideas to authenticated;
grant all on public.profiles,public.ideas to service_role;
grant usage on schema private to service_role;
grant all on all tables in schema private to service_role;
create policy own_profile on public.profiles for select to authenticated using(id=(select auth.uid()));
create policy active_member_ideas on public.ideas for select to authenticated using(not deleted and exists(select 1 from public.profiles where id=(select auth.uid()) and not disabled));
create index ideas_updated on public.ideas(updated_at desc) where not deleted;
create index revisions_idea on private.revisions(idea_id,created_at desc);
create index attribution_creator on private.attribution(creator_id);
create function private.require_member(p_actor uuid,p_admin boolean default false) returns void language plpgsql security definer set search_path=public,private as $$begin if not exists(select 1 from public.profiles where id=p_actor and not disabled and (not p_admin or role='admin')) then raise exception 'access_denied'; end if; end$$;
create function public.consume_limit(p_key text,p_max int,p_seconds int) returns boolean language plpgsql security definer set search_path=public,private as $$declare n int;begin insert into private.limits(key,hits,window_start) values(p_key,1,now()) on conflict(key) do update set hits=case when limits.window_start<now()-make_interval(secs=>p_seconds) then 1 else limits.hits+1 end,window_start=case when limits.window_start<now()-make_interval(secs=>p_seconds) then now() else limits.window_start end returning hits into n;return n<=p_max;end$$;
create function public.create_idea(p_actor uuid,p_data jsonb) returns jsonb language plpgsql security definer set search_path=public,private as $$declare d jsonb; stamp text:=to_char(now() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');begin perform private.require_member(p_actor);d=jsonb_build_object('description','','problem','','solution','','audience','','category','Uncategorized','stage','Captured','notes','[]'::jsonb,'comments','[]'::jsonb,'references','[]'::jsonb)||p_data||jsonb_build_object('version',1,'deleted',false,'created',stamp,'updated',stamp,'history',jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'text','Idea captured','at',stamp)));insert into public.ideas(id,data,accent) values((d->>'id')::uuid,d,lower(d->>'accent'));insert into private.attribution values((d->>'id')::uuid,p_actor);insert into private.audit(actor,action,target) values(p_actor,'Idea captured',(d->>'id')::uuid);return d;end$$;
create function public.update_idea(p_actor uuid,p_id uuid,p_version int,p_patch jsonb) returns jsonb language plpgsql security definer set search_path=public,private as $$declare old public.ideas;d jsonb;event text:='Idea updated';stamp text:=to_char(now() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');begin perform private.require_member(p_actor,p_patch?'deleted');if p_patch - array['title','description','problem','solution','audience','category','stage','notes','comments','references','deleted'] <> '{}'::jsonb then raise exception 'invalid_patch';end if;select * into old from public.ideas where id=p_id for update;if not found then raise exception 'idea_missing';end if;if old.deleted then perform private.require_member(p_actor,true);end if;if old.version<>p_version then raise exception 'version_conflict';end if;if p_patch?'stage' then event:='Moved to '||(p_patch->>'stage');elsif p_patch?'notes' then event:='Notes updated';elsif p_patch?'comments' then event:='Discussion updated';elsif p_patch?'references' then event:='References updated';elsif p_patch?'deleted' then event:=case when (p_patch->>'deleted')::boolean then 'Idea removed' else 'Idea restored' end;end if;insert into private.revisions(idea_id,actor,data) values(p_id,p_actor,old.data);d=old.data||p_patch||jsonb_build_object('version',old.version+1,'updated',stamp,'history',jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'text',event,'at',stamp))||coalesce(old.data->'history','[]'::jsonb));update public.ideas set data=d,version=old.version+1,updated_at=now(),deleted=coalesce((d->>'deleted')::boolean,false) where id=p_id;insert into private.audit(actor,action,target) values(p_actor,event,p_id);return d;end$$;
create function public.check_invitation(p_hash text) returns boolean language sql security definer set search_path=private,public as $$select exists(select 1 from private.invitations where token_hash=p_hash and consumed_at is null and expires_at>now())$$;
create function public.enroll_member(p_hash text,p_id uuid,p_username text) returns void language plpgsql security definer set search_path=private,public as $$begin update private.invitations set consumed_at=now() where token_hash=p_hash and consumed_at is null and expires_at>now();if not found then raise exception 'invalid_invitation';end if;insert into public.profiles(id,username) values(p_id,p_username);end$$;
create function public.create_invitation(p_actor uuid,p_hash text) returns void language plpgsql security definer set search_path=private,public as $$begin perform private.require_member(p_actor,true);insert into private.invitations(token_hash,created_by) values(p_hash,p_actor);insert into private.audit(actor,action) values(p_actor,'Invitation created');end$$;
create function public.set_member_access(p_actor uuid,p_id uuid,p_disabled boolean) returns void language plpgsql security definer set search_path=private,public as $$begin perform private.require_member(p_actor,true);update public.profiles set disabled=p_disabled where id=p_id and role<>'admin';if not found then raise exception 'cannot_modify_admin';end if;insert into private.audit(actor,action,target) values(p_actor,case when p_disabled then 'Member disabled' else 'Member enabled' end,p_id);end$$;
create function public.admin_snapshot(p_actor uuid) returns jsonb language plpgsql security definer set search_path=private,public as $$begin perform private.require_member(p_actor,true);return jsonb_build_object('members',(select coalesce(jsonb_agg(to_jsonb(p)),'[]') from public.profiles p),'history',(select coalesce(jsonb_agg(to_jsonb(a)),'[]') from (select a.id,p.username actor,a.action,a.target,a.created_at from private.audit a join public.profiles p on p.id=a.actor order by a.created_at desc limit 500)a),'attribution',(select coalesce(jsonb_object_agg(idea_id,creator_id),'{}') from private.attribution));end$$;
-- RPCs carrying an actor argument are callable only by the trusted server, never by a member JWT.
revoke all on all functions in schema private from public,anon,authenticated;
revoke all on function public.consume_limit(text,int,int),public.create_idea(uuid,jsonb),public.update_idea(uuid,uuid,int,jsonb),public.check_invitation(text),public.enroll_member(text,uuid,text),public.create_invitation(uuid,text),public.set_member_access(uuid,uuid,boolean),public.admin_snapshot(uuid) from public,anon,authenticated;
grant execute on function public.consume_limit(text,int,int),public.create_idea(uuid,jsonb),public.update_idea(uuid,uuid,int,jsonb),public.check_invitation(text),public.enroll_member(text,uuid,text),public.create_invitation(uuid,text),public.set_member_access(uuid,uuid,boolean),public.admin_snapshot(uuid) to service_role;

-- Private records remain server-only, including if exposed accidentally.
alter table private.attribution enable row level security;
alter table private.revisions enable row level security;
alter table private.invitations enable row level security;
alter table private.audit enable row level security;
alter table private.limits enable row level security;
